select (select jsonb_build_object('s', sum(p.n), 'a', avg(p.n), 'mx', max(p.title), 'sa', string_agg(p.title, ','), 'ba', bool_and(p.n > 0), 'ev', every(p.n > 0), 'aa', array_agg(p.tag), 'oa', jsonb_object_agg(p.title, p.score), 'pc', percentile_cont(0.5) within group (order by p.n), 'mo', mode() within group (order by p.title), 'bo', bit_or(p.n)) from posts p group by p.user_id order by p.user_id limit 1) as j
